/* ---------------------------------------------------------------
   HELPERS
--------------------------------------------------------------- */

function initials(name) {
  return name.split(" ").map((p) => p[0]).slice(0, 2).join("");
}

function fmtDate(d) {
  return new Date(d + "T00:00:00").toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function attendancePct(meetings, memberId) {
  const relevant = meetings.filter((m) => m.status[memberId] !== null && m.status[memberId] !== undefined);
  if (relevant.length === 0) return null;
  const present = relevant.filter((m) => m.status[memberId] === "present").length;
  return Math.round((present / relevant.length) * 100);
}

/* ---------------------------------------------------------------
   SHARED UI PIECES
--------------------------------------------------------------- */

function Avatar({ name, size = 40 }) {
  const hue = useMemo(() => {
    let h = 0;
    for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) % 360;
    return h;
  }, [name]);
  return (
    <div
      style={{
        width: size, height: size, borderRadius: "50%", flexShrink: 0,
        background: `hsl(${hue}, 32%, 30%)`, color: "var(--parchment)",
        display: "flex", alignItems: "center", justifyContent: "center",
        fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: size * 0.38,
        border: "2px solid rgba(239,230,211,0.15)",
      }}
    >
      {initials(name)}
    </div>
  );
}

function BookSpine({ title, author, color, width = 92, height = 132, small }) {
  return (
    <div
      style={{
        width, height, background: `linear-gradient(155deg, ${color}, ${color}dd)`,
        borderRadius: "3px 7px 7px 3px", padding: small ? "10px 8px" : "14px 10px",
        display: "flex", flexDirection: "column", justifyContent: "space-between",
        boxShadow: "0 6px 16px rgba(0,0,0,0.35), inset -3px 0 6px rgba(0,0,0,0.25)",
        flexShrink: 0, position: "relative", overflow: "hidden",
      }}
    >
      <div style={{ position: "absolute", left: 6, top: 0, bottom: 0, width: 1, background: "rgba(255,255,255,0.15)" }} />
      <div style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, color: "var(--parchment)", fontSize: small ? 12 : 15, lineHeight: 1.25 }}>
        {title}
      </div>
      <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", color: "rgba(239,230,211,0.75)", fontSize: small ? 9 : 10.5 }}>
        {author}
      </div>
    </div>
  );
}

function SectionLabel({ children, icon: Icon }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
      {Icon && <Icon size={17} color="var(--brass)" />}
      <h2 style={{ fontFamily: "'Fraunces', serif", fontSize: 19, fontWeight: 600, color: "var(--parchment)", margin: 0 }}>
        {children}
      </h2>
    </div>
  );
}

function Card({ children, style }) {
  return (
    <div
      style={{
        background: "var(--surface)", border: "1px solid rgba(239,230,211,0.08)",
        borderRadius: 12, padding: 18, ...style,
      }}
    >
      {children}
    </div>
  );
}

function ProgressBar({ percent, color = "var(--brass)", height = 8 }) {
  return (
    <div style={{ background: "rgba(239,230,211,0.1)", borderRadius: 99, height, overflow: "hidden" }}>
      <div style={{ width: `${percent}%`, height: "100%", background: color, borderRadius: 99, transition: "width 0.4s ease" }} />
    </div>
  );
}

function Pill({ children, color }) {
  return (
    <span
      style={{
        display: "inline-flex", alignItems: "center", gap: 4, padding: "3px 10px",
        borderRadius: 99, fontSize: 11.5, fontFamily: "'IBM Plex Sans', sans-serif",
        fontWeight: 500, background: `${color}22`, color, border: `1px solid ${color}44`,
      }}
    >
      {children}
    </span>
  );
}

